    const URLS = {};

    function codepointOf(emoji) {
        const out = [];
        for (const ch of emoji) {
            const cp = ch.codePointAt(0);
            if (cp !== 0xfe0f) out.push(cp.toString(16));
        }
        return out.join('-');
    }

    function urlOf(emoji) {
        const cp = codepointOf(emoji);
        if (URLS[cp]) return URLS[cp];
        const svg = SVGS[cp];
        if (!svg) return null;
        return (URLS[cp] = 'data:image/svg+xml;utf8,' + encodeURIComponent(svg));
    }

    function has(emoji) {
        return !!SVGS[codepointOf(emoji)];
    }

    const EMOJI_RE = /(?:[\uD83C-\uDBFF][\uDC00-\uDFFF]|(?![\u2605\u2713\u2717\u2794])[\u2600-\u27BF]|[\u231A\u23EA\u23F8\u25B6\u25C0\u2B05-\u2B07\u2B50\u2B55]|[\u2194-\u2199]\uFE0F)\uFE0F?/g;

    function createImg(emoji) {
        const src = urlOf(emoji);
        if (!src || typeof document === 'undefined' || !document.createElement) return null;
        const img = document.createElement('img');
        img.className = 'twemoji';
        img.alt = emoji;
        img.draggable = false;
        img.decoding = 'async';
        img.src = src;
        return img;
    }

    /** Appends text to `el`, turning every emoji into a Twemoji SVG <img> node. */
    function appendWithTwemoji(el, text) {
        const s = String(text);
        if (!EMOJI_RE.test(s)) {
            el.append(document.createTextNode(s));
            return;
        }
        EMOJI_RE.lastIndex = 0;
        let last = 0, m;
        while ((m = EMOJI_RE.exec(s)) !== null) {
            const img = createImg(m[0]);
            if (!img) continue;
            if (m.index > last) el.append(document.createTextNode(s.slice(last, m.index)));
            el.append(img);
            last = m.index + m[0].length;
        }
        if (last < s.length) el.append(document.createTextNode(s.slice(last)));
    }

    root.ThinkHopTwemoji = {SVGS, codepointOf, urlOf, has, appendWithTwemoji, EMOJI_RE};
